<?php require __DIR__.'/../app/bootstrap.php';$u=role(['admin','kasir','teknisi']);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT id FROM customers WHERE phone=? LIMIT 1");$s->execute([trim($_POST['phone']??'')]);$cid=$s->fetchColumn();if(!$cid){$s=$pdo->prepare("INSERT INTO customers(name,phone)VALUES(?,?)");$s->execute([trim($_POST['customer']),trim($_POST['phone']??'')]);$cid=$pdo->lastInsertId();}$prefix=$pdo->query("SELECT setting_value FROM settings WHERE setting_key='ticket_prefix'")->fetchColumn()?:'SRV';$no=$prefix.'-'.date('Ymd').'-'.str_pad((string)($pdo->query("SELECT COUNT(*) FROM tickets")->fetchColumn()+1),4,'0',STR_PAD_LEFT);$s=$pdo->prepare("INSERT INTO tickets(ticket_no,customer_id,device,serial_number,complaint,technician_id,status,estimated_cost,final_cost,notes)VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$no,$cid,trim($_POST['device']),trim($_POST['serial']),trim($_POST['complaint']),$u['role']==='teknisi'?$u['id']:null,$_POST['status'],max(0,(float)$_POST['estimated']),max(0,(float)$_POST['final']),trim($_POST['notes'])]);audit($pdo,$u['id'],'ticket_create',$no);$pdo->commit();header('Location:tickets.php');exit;}catch(Throwable $e){$pdo->rollBack();http_response_code(500);exit('Failed to save ticket.');}}
$q=trim($_GET['q']??'');$like="%$q%";$s=$pdo->prepare("SELECT t.*,c.name customer,c.phone FROM tickets t JOIN customers c ON c.id=t.customer_id WHERE t.ticket_no LIKE ? OR c.name LIKE ? OR t.device LIKE ? ORDER BY t.id DESC LIMIT 100");$s->execute([$like,$like,$like]);$rows=$s->fetchAll();?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Tiket</title><style>body{font:14px Arial;background:#f5f7fb;margin:0}.top{background:#111827;color:#fff;padding:16px 24px}.top a{color:#fff;margin-left:14px}.wrap{max-width:1200px;margin:25px auto;padding:0 15px}.card{background:#fff;padding:18px;border-radius:12px;border:1px solid #e5e7eb;margin-bottom:15px}.form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form>*{padding:9px}.full{grid-column:1/-1}.btn{background:#2563eb;color:#fff;border:0;padding:10px;border-radius:7px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left;font-size:12px}@media(max-width:700px){.form{grid-template-columns:1fr}.full{grid-column:auto}}</style><div class=top><b>🔧 ServisPro</b><a href=index.php>Dashboard</a><a href=customers.php>Pelanggan</a><a href=parts.php>Sparepart</a><a href=payments.php>Pembayaran</a><a href=logout.php>Keluar</a></div><div class=wrap><h2>Tiket Servis</h2><div class=card><form method=post class=form><input type=hidden name=csrf value="<?=e(csrf())?>"><input name=customer placeholder=Pelanggan required><input name=phone placeholder=WhatsApp><input name=device placeholder=Perangkat required><input name=serial placeholder="No. Seri"><textarea class=full name=complaint placeholder=Keluhan required></textarea><select name=status><option>Diterima</option><option>Diagnosa</option><option>Menunggu</option><option>Dikerjakan</option><option>Selesai</option></select><input name=estimated type=number min=0 placeholder=Estimasi><input name=final type=number min=0 placeholder="Total final"><input name=notes placeholder=Catatan><button class="btn full">Simpan Tiket</button></form></div><div class=card><form><input name=q value="<?=e($q)?>" placeholder="Cari tiket/pelanggan/perangkat"><button class=btn>Cari</button></form><div style=overflow:auto><table><tr><th>ID</th><th>Pelanggan</th><th>Perangkat</th><th>Keluhan</th><th>Status</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['ticket_no'])?></td><td><?=e($r['customer'])?><br><?=e($r['phone'])?></td><td><?=e($r['device'])?></td><td><?=e($r['complaint'])?></td><td><?=e($r['status'])?></td><td>Rp<?=number_format($r['final_cost'],0,',','.')?></td></tr><?php endforeach;?></table></div></div></div>